    namespace AS 业务域,
    metric_name AS 指标名,
    alert_count AS 告警数量,
    @rank := IF(@prev_ns = namespace, @rank + 1, 1) AS 排名,
    @prev_ns := namespace AS dummy
FROM (
    SELECT namespace, metric_name, COUNT(*) AS alert_count
    FROM db_alert_history
    GROUP BY namespace, metric_name
    ORDER BY namespace, alert_count DESC
) t,
(SELECT @rank := 0, @prev_ns := '') r

